css:
.loader { --accent: var(--loader-color); --accent-2: var(--loader-secondary-color); width: var(--loader-size); height: calc(var(--loader-size) * .56); position: relative; display: flex; flex-direction: column; justify-content: space-evenly; overflow: hidden; border-radius: 5px; background: linear-gradient(90deg, color-mix(in srgb, #000 52%, var(--accent-2)), color-mix(in srgb, #000 24%, var(--accent-2))); }
.loader::before { content: ''; position: absolute; inset: 0; background: repeating-linear-gradient(90deg, transparent 0 21%, rgba(255, 255, 255, .26) 21% 23.5%); }
.loader span { position: relative; z-index: 2; border-radius: 2px; background: linear-gradient(90deg, var(--accent), color-mix(in srgb, #fff 48%, var(--accent))); animation: vibrate calc(var(--loader-speed) * .9) ease-in-out infinite; }
.loader span:nth-child(1) { height: 7%; }
.loader span:nth-child(2) { height: 6%; animation-delay: calc(var(--loader-speed) * .1); }
.loader span:nth-child(3) { height: 5%; animation-delay: calc(var(--loader-speed) * .2); }
.loader span:nth-child(4) { height: 4%; animation-delay: calc(var(--loader-speed) * .3); }
.loader span:nth-child(5) { height: 3.4%; animation-delay: calc(var(--loader-speed) * .4); }
@keyframes vibrate { 0%, 100% { transform: scaleY(1); filter: blur(0); } 30% { transform: scaleY(2.8); filter: blur(1px); } 60% { transform: scaleY(1.2); filter: blur(0); } }
